Definition aat_exit (code : Z) (s : APS) (RNG : footprint) (ms : machine_state) : Prop :=
  exists (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
         (F : bvmap 5 word) (fc : bv 32) (m : amem) (lo t : Z) (cdt thr sec : byte) (tm1 dso guard : word),
    ms = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
            F (Z_to_bv 64 AEXIT_PC) fc None m (seg_rom asegs)
    /\ mdtor_pre m
    /\ stk asegs m lo (bv_unsigned sp)
    /\ rw_cells asegs m 0x5ea868 [C4 (Z_to_bv 64 t)]
    /\ rw_cells asegs m 0x60ab80 [C4 (Z_to_bv 64 0)]
    /\ rw_cells asegs m 0x60aba0 [C1 cdt; C1 thr; C1 sec; C1 (Z_to_bv 8 0); C4 tm1]
    /\ (exists reg : bool, atx_stateA reg m)            (* [comment removed for export] *)
    /\ rw_cells asegs m 0xb0400 [C8 (Z_to_bv 64 0xaf1c0); C8 (Z_to_bv 64 0xaf1b0)]
    /\ rw_cells asegs m 0xaf1b0 [C8 (Z_to_bv 64 0x94948); C8 (Z_to_bv 64 0x30768)]
    /\ rw_cells asegs m 0xb4310 [C1 (Z_to_bv 8 0)]
    /\ rw_cells asegs m 0xaf6f8 [C8 (Z_to_bv 64 0x9f128); C8 (Z_to_bv 64 0)]
    /\ rw_cells asegs m 0xb1440 [C8 dso]
    /\ rw_cells asegs m 0x60b008 [C8 (Z_to_bv 64 0)] /\ rw_cells asegs m 0xb3fc0 [C8 (Z_to_bv 64 RSTDIN)] /\ rw_cells asegs m RSTDIN stdin_cells
